import{_ as n,l as s,o as t,c as p,v as e,p as d,x as r,d as l,i,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Chandy–Lamport 快照","description":"","frontmatter":{"title":"Chandy–Lamport 快照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chandy-lamport.md","filePath":"cs/chandy-lamport.md","lastUpdated":1789023840000}'),h={name:"cs/chandy-lamport.md"};function c(m,a,A,_,B,u){const o=s("Mermaid");return t(),p("div",null,[a[1]||(a[1]=e('<h1 id="chandy–lamport-快照" tabindex="-1">Chandy–Lamport 快照 <a class="header-anchor" href="#chandy–lamport-快照" aria-label="Permalink to &quot;Chandy–Lamport 快照&quot;">​</a></h1><div class="epigraph"><p>没有全局时刻，也能切一刀：标记沿 FIFO 信道走，进程记录本地状态，信道记录标记前的在途消息。切出的是一致割。</p><footer>—— 据 Chandy and Lamport, Distributed Snapshots, TOCS 1985 整理</footer></div><p>上一课<a href="/cs/hlc">HLC</a>给了可读时间戳，仍不是「所有进程同一瞬间」。缺口是<strong>全局状态</strong>：死锁检测、检查点、算账要对一个从未同时存在过的组合状态说话。本课不靠 NTP，不靠向量比较出全局时刻。后课故障检测器问的是「谁活着」，不是「系统此刻的变量」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一致全局状态：割不包含「已收未发」——若割里有收事件，对应发事件也在割里。任意时刻把各机内存 dump 拼起来，可能看见收到了从未发送的消息。缺口是算法：在异步 FIFO 信道上，用<strong>标记消息</strong>构造一致割。</p><p>Chandy–Lamport：发起者记录自己的状态，向所有出信道发标记。进程第一次收到标记：记录状态，向尚未发过标记的出信道补发，并开始记录该入信道上标记之前的消息（信道状态）。每条信道的标记最多一次。有限步后得到快照。</p><p><span class="marginnote">假设信道 FIFO、可靠，进程不故障——与崩溃模型正交。Lai–Yang 等变体放松 FIFO，本课点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现检查点：快照状态 + 信道在途，作为回滚目标。死锁检测：在快照的等待图上找环。本课只保证一致性，不保证「最近」：快照对应某个可能曾出现的全局状态，不一定是触发瞬间。</p>',9)),(t(),d(E,null,{default:r(()=>[i(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22%E5%8F%91%E8%B5%B7%E8%80%85%E8%AE%B0%E7%8A%B6%E6%80%81%E5%B9%B6%E5%8F%91%E6%A0%87%E8%AE%B0%22%5D%20--%3E%20RECV%5B%22%E9%A6%96%E6%AC%A1%E6%94%B6%E6%A0%87%E8%AE%B0%3A%20%E8%AE%B0%E7%8A%B6%E6%80%81%22%5D%0A%20%20RECV%20--%3E%20FWD%5B%22%E5%90%91%E5%87%BA%E4%BF%A1%E9%81%93%E5%8F%91%E6%A0%87%E8%AE%B0%22%5D%0A%20%20RECV%20--%3E%20CHAN%5B%22%E8%AE%B0%E5%BD%95%E6%A0%87%E8%AE%B0%E5%89%8D%E7%9A%84%E5%85%A5%E6%B6%88%E6%81%AF%22%5D%0A%20%20CHAN%20--%3E%20CUT%5B%22%E4%B8%80%E8%87%B4%E5%89%B2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>与向量钟：可以用向量定义一致割（每个进程选一个事件，集合向下封闭），那是判定；Chandy–Lamport 是<strong>构造</strong>。两者互补。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FIFO 保证：标记之后的消息不会跑到标记前面被记进信道，从而避免「先收后发」穿割。可靠投递保证标记终到达。进程故障时算法要重做或改用因果日志——那是恢复协议，不是本课。</p><p>快照期间应用继续跑，这是相对「停全世界」的优点。代价是信道记录缓冲区，以及「快照不是实时」：检测到的死锁是快照里的死锁，可能已经自行解开。活性检测要反复拍。</p><p>本课不把数据库的 fuzzy checkpoint、ARIES 的脏页表写成分布式快照：那是单机恢复。也不把云厂商的 VM snapshot 当 Chandy–Lamport：那些通常靠存储层冻结，有近乎同步的假设。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理非 FIFO、不处理拜占庭标记。不把快照当线性一致读。后课默认：要全局谓词（死锁、终止），先拍一致割再在割上评价；墙钟对齐不是合法手段。故障检测下一课，用超时与怀疑，不用快照当心跳。</p><p>一致割让「分布式状态」有对象。没有它，监控里拼出来的 JSON 只是并发读的杂烩。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一致割：没有未发送却已接收的消息。</li><li>标记 + FIFO 构造快照；应用不必停。</li><li>快照是可能状态，不必是触发瞬间。</li><li>出处：Chandy and Lamport, TOCS 1985。</li></ul>',10))])}const F=n(h,[["render",c]]);export{f as __pageData,F as default};
